import type { CapabilityMatrix, CapabilityStatus } from "@tavern-canvas/contracts";

import type { HostCapabilityId } from "./host_adapter.js";
import { inspect_sillytavern, type SillyTavernInspection } from "./sillytavern_host.js";
import { inspect_tauritavern, type TauriTavernInspection } from "./tauritavern_host.js";
import { inspect_tavern_helper, type TavernHelperInspection } from "./tavern_helper_host.js";

export const MINIMUM_TAVERN_HELPER_VERSION = "4.9.1";

/**
 * The semver.org reference grammar, plus the two liberties the `semver` package's own `valid()`
 * took and hosts may already rely on: surrounding whitespace and a leading `v`. The probe needs
 * exactly the two checks `valid()` and `gte()` gave it, and pulling that package in for them cost
 * ~28 KB of the extension's initial chunk, so both live here instead. Build metadata is matched
 * and then ignored, the same way `valid("1.2.3+build")` accepted it.
 */
const SEMVER_PATTERN =
  /^v?(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-((?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*)(?:\.(?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*))*))?(?:\+[0-9a-zA-Z-]+(?:\.[0-9a-zA-Z-]+)*)?$/u;

interface ParsedVersion {
  readonly major: number;
  readonly minor: number;
  readonly patch: number;
  readonly prerelease: string | null;
}

function parse_semver(version: string): ParsedVersion | null {
  const match = SEMVER_PATTERN.exec(version.trim());
  if (match === null) {
    return null;
  }
  const [, major, minor, patch, prerelease] = match;
  return {
    major: Number(major),
    minor: Number(minor),
    patch: Number(patch),
    prerelease: prerelease ?? null,
  };
}

function is_at_least(version: ParsedVersion, minimum: ParsedVersion): boolean {
  const core_order =
    version.major - minimum.major || version.minor - minimum.minor || version.patch - minimum.patch;
  if (core_order !== 0) {
    return core_order > 0;
  }
  // Equal release cores: a prerelease sorts below its own release (semver 11.3), so 4.9.1-rc.1 is
  // not yet 4.9.1. Ordering two prereleases of the same core against each other is deliberately
  // not implemented -- `minimum` is only ever MINIMUM_TAVERN_HELPER_VERSION, a plain release.
  return version.prerelease === null;
}

type HelperVersionVerdict = "invalid" | "unsupported" | "supported";

function classify_helper_version(version: string): HelperVersionVerdict {
  const parsed = parse_semver(version);
  const minimum = parse_semver(MINIMUM_TAVERN_HELPER_VERSION);
  if (parsed === null || minimum === null) {
    return "invalid";
  }
  return is_at_least(parsed, minimum) ? "supported" : "unsupported";
}

export type BootstrapProbeResult =
  | {
      ready: true;
      matrix: CapabilityMatrix;
      helper_version: string;
    }
  | {
      ready: false;
      error_code:
        | "tavern_helper_missing"
        | "helper_version_invalid"
        | "helper_version_unsupported"
        | "helper_api_incomplete";
      missing_capabilities: string[];
      /**
       * The detected (but unsupported) TavernHelper version -- only ever populated for
       * `helper_version_unsupported`, the one blocked variant where a valid, parseable, too-old
       * version string genuinely exists. The other blocked variants (missing, invalid, API
       * incomplete) have no reliable version to report here. Threads through to the Studio
       * shell's blocked-state copy (`app.unsupported_host.description`'s `{current_version}`).
       */
      current_version?: string;
    };

const REQUIRED_CAPABILITY_IDS = [
  "main_generation_events",
  "private_prompt_generation",
  "message_swipe_metadata",
  "host_image_upload",
  "tavern_helper",
] as const satisfies readonly HostCapabilityId[];

function unavailable(reason: string): CapabilityStatus {
  return { available: false, reason };
}

function available_when(value: boolean, reason: string): CapabilityStatus {
  return value ? { available: true } : unavailable(reason);
}

function read_global(value: unknown, property_name: string): unknown {
  if ((typeof value !== "object" || value === null) && typeof value !== "function") {
    return undefined;
  }
  try {
    return Reflect.get(value, property_name);
  } catch {
    return undefined;
  }
}

function build_matrix(
  helper: TavernHelperInspection,
  sillytavern: SillyTavernInspection,
  tauri: TauriTavernInspection,
): CapabilityMatrix {
  return {
    native_tool_manager: available_when(
      sillytavern.native_tool_manager,
      "SillyTavern ToolManager API is unavailable",
    ),
    main_generation_events: available_when(
      sillytavern.main_generation_events,
      "SillyTavern generation event API is unavailable",
    ),
    private_prompt_generation: available_when(
      helper.private_prompt_generation,
      "TavernHelper.generateRaw is unavailable",
    ),
    message_swipe_metadata: available_when(
      helper.message_swipe_metadata && sillytavern.message_swipe_metadata,
      "TavernHelper message swipe API is unavailable",
    ),
    host_image_upload: available_when(
      sillytavern.host_image_upload,
      "SillyTavern image upload API is unavailable",
    ),
    tavern_helper: available_when(
      helper.version.state === "available",
      "TavernHelper version API is unavailable",
    ),
    tauri_chat_surface: available_when(
      tauri.tauri_chat_surface,
      "TauriTavern ChatSurface API is unavailable",
    ),
    tauri_world_info_activation: available_when(
      tauri.tauri_world_info_activation,
      "TauriTavern WorldInfo activation API is unavailable",
    ),
    gateway_protocol: unavailable("Gateway protocol is not connected"),
  };
}

function missing_required_capabilities(matrix: CapabilityMatrix): string[] {
  return REQUIRED_CAPABILITY_IDS.filter(
    (capability_id: HostCapabilityId) => matrix[capability_id]?.available !== true,
  );
}

export function probe_host_capabilities(globals: unknown): BootstrapProbeResult {
  const helper = inspect_tavern_helper(read_global(globals, "TavernHelper"));
  const sillytavern = inspect_sillytavern(
    read_global(globals, "SillyTavern"),
    read_global(globals, "fetch"),
  );
  const tauri = inspect_tauritavern(read_global(globals, "__TAURITAVERN__"));
  const matrix = build_matrix(helper, sillytavern, tauri);

  if (!helper.detected) {
    return {
      ready: false,
      error_code: "tavern_helper_missing",
      missing_capabilities: missing_required_capabilities(matrix),
    };
  }
  const version = helper.version;

  if (version.state === "missing" || version.state === "threw") {
    return {
      ready: false,
      error_code: "helper_api_incomplete",
      missing_capabilities: missing_required_capabilities(matrix),
    };
  }

  if (version.state === "invalid") {
    return {
      ready: false,
      error_code: "helper_version_invalid",
      missing_capabilities: ["tavern_helper"],
    };
  }

  const helper_version = version.value;
  const verdict = classify_helper_version(helper_version);
  if (verdict === "invalid") {
    return {
      ready: false,
      error_code: "helper_version_invalid",
      missing_capabilities: ["tavern_helper"],
    };
  }

  if (verdict === "unsupported") {
    return {
      ready: false,
      error_code: "helper_version_unsupported",
      missing_capabilities: ["tavern_helper"],
      current_version: helper_version,
    };
  }

  const missing_capabilities = missing_required_capabilities(matrix);
  if (missing_capabilities.length > 0) {
    return {
      ready: false,
      error_code: "helper_api_incomplete",
      missing_capabilities,
    };
  }

  return { ready: true, matrix, helper_version };
}
